        for i, (a, b) in enumerate(remaining):
            rest = remaining[:i] + remaining[i + 1:]
            if chain:
                if a == last:
                    result = backtrack(rest, chain + [(a, b)])
                    if result is not None:
                        return result
                if b == last:
                    result = backtrack(rest, chain + [(b, a)])
                    if result is not None:
                        return result
            else:
                # The first domino can start in either orientation.
                for d in ((a, b), (b, a)):
                    result = backtrack(rest, chain + [d])
                    if result is not None:
                        return result
        return None

    return backtrack(list(dominoes), [])

